fn layer_to_json(layer: &Layer) -> Json {
        obj(vec![("name", Json::String(layer.name.clone())), ("color", Json::Number(layer.color.index().unwrap_or(7) as f64)), ("linetype", Json::String(layer.line_type_name.clone()))])
